// type: CKGTN 
`timescale 1ns/1ps
`celldefine
module CKGTNX0P5_9TLVT (QN, CKN, E, TE, VDD, VNW, VPW, VSS);
	output QN;
	input CKN, E, TE;
	reg notifier;
	wire delayed_CKN, delayed_E, delayed_TE;
	(* pg_type = "primary_power" *) inout VDD;
	(* pg_type = "nwell" *) inout VNW;
	(* pg_type = "pwell" *) inout VPW;
	(* pg_type = "primary_ground" *) inout VSS;
`ifdef no_power_gate
	initial force VDD = 1'b1;
	initial force VNW = 1'b1;
	initial force VPW = 1'b0;
	initial force VSS = 1'b0;
`endif


	// Function
	wire __PWD_DWN_OUT__QN, delayed_CKN__bar, int_fwire_0;
	wire int_fwire_clk, int_fwire_PM, int_fwire_QN;
	wire int_fwire_test, VDD__bar, VNW__bar;

	buf (int_fwire_clk, delayed_CKN);
	or (int_fwire_test, delayed_E, delayed_TE);
	empyrean_latch (int_fwire_PM, notifier, int_fwire_clk, int_fwire_test);
	not (delayed_CKN__bar, delayed_CKN);
	and (int_fwire_0, int_fwire_PM, delayed_CKN__bar);
	not (int_fwire_QN, int_fwire_0);
	not (VNW__bar, VNW);
	not (VDD__bar, VDD);
	or (__PWD_DWN_OUT__QN, VDD__bar, VSS, VNW__bar, VPW);
	empyrean_power_down (QN, int_fwire_QN, __PWD_DWN_OUT__QN);

	// Timing

	// Additional timing wires
	wire adacond_NOT_E, adacond_NOT_TE;


	// Additional timing gates
	not (adacond_NOT_TE, TE);
	not (adacond_NOT_E, E);

	specify
		if (E == 1'b1 && TE == 1'b1)
			(CKN => QN) = 0;
		if (E == 1'b1 && TE == 1'b0)
			(CKN => QN) = 0;
		if (E == 1'b0 && TE == 1'b1)
			(CKN => QN) = 0;
		if (E == 1'b0 && TE == 1'b0)
			(posedge CKN => (QN+:1'b1)) = 0;
		$setuphold (negedge CKN &&& adacond_NOT_TE == 1'b1, posedge E &&& adacond_NOT_TE == 1'b1, 0, 0, notifier,,, delayed_CKN, delayed_E);
		$setuphold (negedge CKN &&& adacond_NOT_TE == 1'b1, negedge E &&& adacond_NOT_TE == 1'b1, 0, 0, notifier,,, delayed_CKN, delayed_E);
		$setuphold (negedge CKN &&& adacond_NOT_E == 1'b1, posedge TE &&& adacond_NOT_E == 1'b1, 0, 0, notifier,,, delayed_CKN, delayed_TE);
		$setuphold (negedge CKN &&& adacond_NOT_E == 1'b1, negedge TE &&& adacond_NOT_E == 1'b1, 0, 0, notifier,,, delayed_CKN, delayed_TE);
		$width (posedge CKN, 0, 0, notifier);
		$width (negedge CKN, 0, 0, notifier);
	endspecify
endmodule
`endcelldefine

