	not (delayed_SN__bar, delayed_SN);
	and (int_fwire_0, delayed_RN, delayed_SN__bar);
	and (int_fwire_1, delayed_D, delayed_RN);
	or (int_fwire_d, int_fwire_1, int_fwire_0);
	buf (xcr_0, 0);
	empyrean_dff (int_fwire_IQ, notifier, delayed_CK, int_fwire_d, xcr_0);
	buf (int_fwire_Q, int_fwire_IQ);
	not (VNW__bar, VNW);
	not (VDD__bar, VDD);
	or (__PWD_DWN_OUT__Q, VDD__bar, VSS, VNW__bar, VPW);
