	and (adacond_D_AND_SN, D, SN);
	not (SN__bar, SN);
	and (adacond_D_AND_NOT_SN, D, SN__bar);
	not (D__bar, D);
	and (adacond_NOT_D_AND_NOT_SN, D__bar, SN__bar);
