		$setuphold (posedge CK &&& adacond_E == 1'b1, negedge D &&& adacond_E == 1'b1, 0, 0, notifier,,, delayed_CK, delayed_D);
		$setuphold (posedge CK &&& adacond_D == 1'b1, posedge E &&& adacond_D == 1'b1, 0, 0, notifier,,, delayed_CK, delayed_E);
		$setuphold (posedge CK &&& adacond_D == 1'b1, negedge E &&& adacond_D == 1'b1, 0, 0, notifier,,, delayed_CK, delayed_E);
		$setuphold (posedge CK &&& adacond_NOT_D == 1'b1, posedge E &&& adacond_NOT_D == 1'b1, 0, 0, notifier,,, delayed_CK, delayed_E);
		$setuphold (posedge CK &&& adacond_NOT_D == 1'b1, negedge E &&& adacond_NOT_D == 1'b1, 0, 0, notifier,,, delayed_CK, delayed_E);
